import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Fill contact form, then go back and re-fill with different filter', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'Test User')
  await opFill(page, 'Email', 'test@example.com')
  await opFill(page, 'Message', 'Inquiry about performance testing services')
  await opClick(page, 'button', 'Submit')
  await opClick(page, 'link', 'Contact')
  await opClick(page, 'combobox', 'Which service are you interested in')
  await opPress(page, 'ArrowDown')
  await opPress(page, 'Enter')
  await opSeen(page, 'heading', 'Contact')
})
